#!/bin/bash

# Reference kernel boot harness.
#
# Boots a reference Image under one QEMU lane with a fresh per-flight nonce,
# and validates the ordered boot predicate:
#
#   EVO_INIT_ALIVE
#   EVO_BOOT_NONCE <exact injected nonce>
#   EVO_INIT_DONE
#   <controlled poweroff; QEMU exits 0 without timeout>
#
# The nonce is generated by the caller per flight and never reused, so a
# replayed serial log from any earlier flight fails the exact-match check.

set -eu
set -o pipefail

export LC_ALL=C TZ=UTC

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd -P)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd -P)"
JQ="${C30_JQ:-/opt/homebrew/bin/jq}"
TIMEOUT_BIN="${C30_TIMEOUT:-/opt/homebrew/bin/timeout}"

KERNEL_CONTRACT="$PROJECT_ROOT/contracts/kernel-target.json"

usage() {
  printf 'usage: %s <image> <initramfs> <lane-name> <nonce> <serial-log>\n' "$0" >&2
  exit 2
}

[ "$#" -eq 5 ] || usage

IMAGE="$1"
INITRAMFS="$2"
LANE="$3"
NONCE="$4"
SERIAL_LOG="$5"

QEMU_BIN="$("$JQ" -r '.qemu.binaryPath' "$KERNEL_CONTRACT")"
QEMU_SHA_EXPECTED="$("$JQ" -r '.qemu.binarySha256' "$KERNEL_CONTRACT")"
QEMU_SHA_ACTUAL="$(/usr/bin/shasum -a 256 "$QEMU_BIN" | awk '{print $1}')"
[ "$QEMU_SHA_ACTUAL" = "$QEMU_SHA_EXPECTED" ] || {
  printf 'boot: QEMU binary drifted: %s != %s\n' "$QEMU_SHA_ACTUAL" "$QEMU_SHA_EXPECTED" >&2
  exit 1
}

case "$LANE" in
  hvf-host)       ACCEL_ARGS="-accel hvf -cpu host" ;;
  tcg-cortex-a72) ACCEL_ARGS="-accel tcg -cpu cortex-a72" ;;
  *) printf 'boot: unknown lane %s\n' "$LANE" >&2; exit 2 ;;
esac

MACHINE="$("$JQ" -r '.qemu.machine' "$KERNEL_CONTRACT")"
SMP="$("$JQ" -r '.qemu.fixedArgv.smp' "$KERNEL_CONTRACT")"
MEM="$("$JQ" -r '.qemu.fixedArgv.memoryMiB' "$KERNEL_CONTRACT")"

# TCG is a slow witness; HVF is fast. Both get generous but finite ceilings so
# a hung boot fails as TIMEOUT instead of passing by patience.
case "$LANE" in
  hvf-host)       BOOT_TIMEOUT=120 ;;
  tcg-cortex-a72) BOOT_TIMEOUT=600 ;;
esac

set +e
"$TIMEOUT_BIN" "$BOOT_TIMEOUT" "$QEMU_BIN" \
  -M "$MACHINE",dtb-randomness=off \
  $ACCEL_ARGS \
  -smp "$SMP" \
  -m "$MEM" \
  -kernel "$IMAGE" \
  -initrd "$INITRAMFS" \
  -append "console=ttyAMA0 panic=-1 evo_nonce=$NONCE" \
  -nographic \
  -no-reboot \
  > "$SERIAL_LOG" 2>&1
qemu_rc=$?
set -e

if [ "$qemu_rc" -eq 124 ]; then
  printf 'boot: TIMEOUT after %ss on %s\n' "$BOOT_TIMEOUT" "$LANE" >&2
  exit 1
fi
if [ "$qemu_rc" -ne 0 ]; then
  printf 'boot: QEMU exited %d on %s\n' "$qemu_rc" "$LANE" >&2
  exit 1
fi

# Ordered predicate over byte offsets. Kernel printk and init stdout share
# the serial console and may interleave between markers, so markers are
# matched as exact fixed substrings (never inside another token) and their
# byte offsets must be strictly increasing. The nonce's entropy makes a
# forged substring match infeasible.
alive_off="$(grep -a -b -o -F 'EVO_INIT_ALIVE' "$SERIAL_LOG" | head -1 | cut -d: -f1 || true)"
nonce_off="$(grep -a -b -o -F "EVO_BOOT_NONCE $NONCE" "$SERIAL_LOG" | head -1 | cut -d: -f1 || true)"
done_off="$(grep -a -b -o -F 'EVO_INIT_DONE' "$SERIAL_LOG" | head -1 | cut -d: -f1 || true)"

if [ -z "$alive_off" ] || [ -z "$nonce_off" ] || [ -z "$done_off" ]; then
  printf 'boot: predicate markers missing on %s\n' "$LANE" >&2
  exit 1
fi
if [ "$alive_off" -ge "$nonce_off" ] || [ "$nonce_off" -ge "$done_off" ]; then
  printf 'boot: predicate markers out of order on %s\n' "$LANE" >&2
  exit 1
fi

nonce_count="$(grep -a -c -F "EVO_BOOT_NONCE $NONCE" "$SERIAL_LOG")"
if [ "$nonce_count" -ne 1 ]; then
  printf 'boot: nonce appears %s times, expected exactly 1\n' "$nonce_count" >&2
  exit 1
fi

printf 'boot: PASS on %s (nonce verified, ordered markers, controlled shutdown)\n' "$LANE"

# Emit a machine-readable flight receipt so the acceptance gate can re-validate
# the predicate from the serial log and nonce without rerunning QEMU.
image_sha="$(/usr/bin/shasum -a 256 "$IMAGE" | awk '{print $1}')"
log_sha="$(/usr/bin/shasum -a 256 "$SERIAL_LOG" | awk '{print $1}')"
receipts="$PROJECT_ROOT/.build/reference/flight-receipts.jsonl"
mkdir -p "$(dirname "$receipts")"
"${C30_JQ:-/opt/homebrew/bin/jq}" -cn \
  --arg image "$IMAGE" \
  --arg imageSha256 "$image_sha" \
  --arg lane "$LANE" \
  --arg nonce "$NONCE" \
  --arg serialLog "$SERIAL_LOG" \
  --arg serialLogSha256 "$log_sha" \
  --arg flownAt "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" \
  '{image:$image,imageSha256:$imageSha256,lane:$lane,nonce:$nonce,serialLog:$serialLog,serialLogSha256:$serialLogSha256,flownAt:$flownAt}' \
  >> "$receipts"
